  header{position:sticky;top:0;z-index:100;height:76px;padding:0 28px;background:linear-gradient(135deg,var(--teal-dark),var(--teal));display:flex;align-items:center;justify-content:space-between;color:#fff;box-shadow:0 12px 30px rgba(0,0,0,.15)}
  .brand h1{font-family:'Playfair Display',serif;font-size:2.2rem;line-height:1}.brand p{font-size:1.22rem;font-weight:700;opacity:.98;margin-top:6px}
