  .notify-wrap{position:relative}.notify-btn{position:relative;width:46px;height:46px;border-radius:50%;border:1px solid rgba(255,255,255,.32);background:rgba(255,255,255,.14);color:#fff;cursor:pointer}.notify-count{position:absolute;top:-4px;right:-1px;min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:#ff5252;color:#fff;font-size:.72rem;font-weight:700;display:none;align-items:center;justify-content:center}.notify-count.show{display:flex}
  .notify-panel{position:absolute;top:58px;right:0;width:350px;max-height:420px;overflow:auto;background:#fff;border-radius:18px;box-shadow:0 24px 50px rgba(0,0,0,.18);padding:14px;display:none;color:var(--text)}.notify-panel.active{display:block}.notify-panel h3{font-family:'Playfair Display',serif;font-size:1.08rem;color:var(--teal-dark);margin-bottom:4px}.notify-panel p{font-size:.8rem;color:var(--muted);margin-bottom:12px}
  .notify-item{background:#f8fbfb;border:1px solid #edf4f4;border-radius:14px;padding:12px;margin-bottom:10px}.notify-top{display:flex;justify-content:space-between;gap:10px;margin-bottom:6px}.notify-title{font-size:.88rem;font-weight:700}.notify-meta{font-size:.78rem;color:#6e7f7f;line-height:1.45}
  .status{display:inline-block;padding:4px 12px;border-radius:999px;font-size:.76rem;font-weight:700}.pending{background:#fff3cd;color:#8a6500}.confirmed{background:#e8f5e9;color:#2e7d32}.cancelled{background:#ffebee;color:#c62828}
  .top-tabs{max-width:1200px;margin:28px auto 0;padding:0 24px;display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap}.tabs{display:inline-flex;background:#fff;border-radius:999px;box-shadow:var(--shadow);overflow:hidden}.tab{border:none;background:none;padding:12px 28px;font-size:.94rem;font-weight:700;cursor:pointer;color:#768989}.tab.active{background:var(--teal);color:#fff}
  .browse-tools{display:flex;justify-content:flex-end;align-items:center;gap:12px;flex:0 0 auto}.search-wrap{width:min(360px,100%);position:relative}.search-wrap input{width:100%;padding:13px 18px;border:1.5px solid #d7e8e6;border-radius:999px;background:#fff;box-shadow:var(--shadow);font-size:.95rem;outline:none}.search-wrap input:focus{border-color:var(--teal-light)}
  .main{max-width:1200px;margin:0 auto;padding:22px 24px 60px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:24px}.card{background:#fff;border-radius:24px;overflow:hidden;box-shadow:var(--shadow);transition:transform .25s}.card:hover{transform:translateY(-8px)}.media{position:relative;height:220px}.media img{width:100%;height:100%;object-fit:cover}
  .hover{position:absolute;inset:0;padding:18px;background:linear-gradient(180deg,rgba(8,24,24,.08),rgba(8,24,24,.84));color:#fff;opacity:0;transition:opacity .25s;display:flex;flex-direction:column;justify-content:flex-end}.card:hover .hover{opacity:1}.hover p{font-size:.84rem;line-height:1.5;margin:8px 0 12px}.badges{display:flex;flex-wrap:wrap;gap:8px}.badges span{padding:6px 10px;border-radius:999px;background:rgba(255,255,255,.16);font-size:.74rem}
