  .booking-card{background:#fff;border-radius:22px;overflow:hidden;box-shadow:var(--shadow);margin-bottom:20px}.booking-head{background:linear-gradient(135deg,rgba(0,121,107,.88),rgba(0,150,136,.82)),var(--booking-bg);background-size:cover;background-position:center;color:#fff;padding:16px 22px;display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.booking-body{position:relative;padding:24px;display:flex;justify-content:space-between;gap:22px;flex-wrap:wrap;overflow:hidden}.booking-body::before{content:'';position:absolute;inset:0;background-image:var(--booking-bg);background-size:cover;background-position:center;filter:blur(5px);transform:scale(1.05);opacity:.58}.booking-body::after{content:'';position:absolute;inset:0;background:rgba(255,255,255,.46)}.booking-body>*{position:relative;z-index:1}
  .booking-list{display:grid;gap:12px}.booking-line{display:flex;gap:12px;align-items:flex-start}.booking-line strong{display:block;font-size:.8rem;color:#617777}.booking-line span{font-size:1rem;font-weight:700}.summary{min-width:260px;background:linear-gradient(135deg,#e2f6f4,#c2e8e4);border-radius:18px;padding:18px;text-align:center}.summary .big{font-size:1.8rem;font-weight:700;color:var(--teal-dark)}.summary .small{font-size:.8rem;color:#5e7676;line-height:1.55;margin-top:8px}
  .cancel-btn{margin-top:14px;width:100%;border:none;border-radius:999px;padding:11px;background:#f44336;color:#fff;font-weight:700;cursor:pointer}
