<div class="overlay" id="booking-modal"><div class="modal"><button class="close" type="button" onclick="closeBookingModal()">&times;</button><h2 id="booking-title">Book Cottage</h2><p class="sub">Choose your stay dates, times, number of guests, and review the down payment before confirming.</p><div class="booking-layout"><div><div class="form-grid two"><div class="group" style="grid-column:1/-1"><label>Cottage</label><input id="booking-cottage-name" type="text" readonly></div><div class="group"><label>Number of Guests</label><input type="number" min="1" id="booking-guest-count" value="1"></div><div class="group"><label>Capacity</label><input id="booking-capacity" type="text" readonly></div><div class="group"><label>Check-In Date</label><input type="date" id="checkin-date"></div><div class="group"><label>Check-In Time</label><input type="time" id="checkin-time" value="14:00"></div><div class="group"><label>Check-Out Date</label><input type="date" id="checkout-date"></div><div class="group"><label>Check-Out Time</label><input type="time" id="checkout-time" value="12:00"></div></div><div class="avail" id="availability-status">Select dates to check availability.</div><div class="error" id="book-error"></div><div class="success" id="book-success"></div><div class="actions-row"><button class="btn secondary" type="button" onclick="closeBookingModal()">Cancel</button><button class="btn primary" id="confirm-booking-btn" type="button" onclick="confirmBooking()">Confirm Booking</button></div></div><div class="side"><div class="box"><div style="font-size:.84rem;color:#6d8484;margin-bottom:6px">Total Amount</div><div class="value" id="booking-total">PHP 0</div><div class="note" id="booking-total-meta">Choose dates to compute the total.</div></div><div class="box"><div style="font-size:.84rem;color:#6d8484;margin-bottom:6px">Down Payment</div><div class="value" id="booking-down-payment">PHP 0</div><div class="note">A 30% down payment reference is saved with your booking.</div></div><div class="qr"><img src="<?= $gcashQrAsset ?>" alt="GCash QR"><strong style="display:block;color:var(--teal-dark);margin-bottom:6px">GCash QR</strong><div class="note">Use this QR reference for your down payment after submitting the booking.</div></div></div></div></div></div>

<div class="overlay" id="profile-modal"><div class="modal small"><button class="close" type="button" onclick="closeProfileModal()">&times;</button><h2>My Profile</h2><p class="sub">Update your name, phone, theme, and password from here.</p><div class="form-grid two"><div class="group"><label>Full Name</label><input type="text" id="profile-full-name"></div><div class="group"><label>Email</label><input type="email" id="profile-email" readonly></div><div class="group"><label>Phone Number</label><input type="text" id="profile-phone"></div><div class="group"><label>Theme</label><select id="profile-theme"><option value="teal">Teal</option><option value="sunset">Sunset</option><option value="ocean">Ocean</option></select></div></div><div class="form-grid two" style="margin-top:16px"><div class="group"><label>Current Password</label><input type="password" id="profile-current-password"></div><div class="group"><label>New Password</label><input type="password" id="profile-new-password"></div><div class="group" style="grid-column:1/-1"><label>Confirm New Password</label><input type="password" id="profile-confirm-password"></div></div><div class="error" id="profile-error"></div><div class="success" id="profile-success"></div><div class="actions-row"><button class="btn secondary" type="button" onclick="closeProfileModal()">Close</button><button class="btn primary" type="button" onclick="saveProfile()">Save Profile</button></div></div></div>

<script>
let cottages=[],currentCottage=null,bookings=[],selectedAvailable=false,profile=null,refreshTimer=null;
const today=(new Date()).toISOString().split('T')[0],themes=['teal','sunset','ocean'];
function showTab(tab){document.getElementById('pane-browse').style.display=tab==='browse'?'':'none';document.getElementById('pane-bookings').style.display=tab==='bookings'?'':'none';document.getElementById('tab-browse').classList.toggle('active',tab==='browse');document.getElementById('tab-bookings').classList.toggle('active',tab==='bookings');if(tab==='bookings')loadMyBookings()}
function money(v){return 'PHP '+Number(v||0).toLocaleString()}
function setTheme(theme){document.body.dataset.theme=theme;document.getElementById('profile-theme').value=theme;document.getElementById('theme-button').textContent='Theme: '+theme.charAt(0).toUpperCase()+theme.slice(1)}
function cycleTheme(){const current=document.body.dataset.theme||'teal';const next=themes[(themes.indexOf(current)+1)%themes.length];setTheme(next);if(profile){profile.display_theme=next}saveProfile(false)}
async function loadProfile(){try{const fd=new FormData();fd.append('action','profile');const res=await fetch('auth.php',{method:'POST',body:fd,cache:'no-store'});const data=await res.json();if(!data.success)return;profile=data.profile;document.getElementById('profile-full-name').value=profile.full_name||'';document.getElementById('profile-email').value=profile.email||'';document.getElementById('profile-phone').value=profile.phone||'';document.getElementById('profile-theme').value=profile.display_theme||'teal';document.getElementById('profile-name-display').textContent=profile.full_name||'';setTheme(profile.display_theme||'teal')}catch(e){console.error('Profile load failed',e)}}
function openProfileModal(){document.getElementById('profile-error').style.display='none';document.getElementById('profile-success').style.display='none';openModal('profile')}
function closeProfileModal(){closeModal('profile')}
async function saveProfile(showMessage=true){const err=document.getElementById('profile-error'),ok=document.getElementById('profile-success');err.style.display='none';ok.style.display='none';const fd=new FormData();fd.append('action','update_profile');fd.append('full_name',document.getElementById('profile-full-name').value);fd.append('phone',document.getElementById('profile-phone').value);fd.append('display_theme',document.getElementById('profile-theme').value);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){if(showMessage){err.textContent=data.message||'Could not update profile.';err.style.display='block'}return false}profile={...(profile||{}),...data.profile,email:document.getElementById('profile-email').value};document.getElementById('profile-name-display').textContent=data.profile.full_name;setTheme(data.profile.display_theme);const current=document.getElementById('profile-current-password').value,newPass=document.getElementById('profile-new-password').value,confirm=document.getElementById('profile-confirm-password').value;if(current||newPass||confirm){const pw=new FormData();pw.append('action','change_password');pw.append('current_password',current);pw.append('new_password',newPass);pw.append('confirm_password',confirm);const pwRes=await fetch('auth.php',{method:'POST',body:pw});const pwData=await pwRes.json();if(!pwData.success){if(showMessage){err.textContent=pwData.message||'Could not change password.';err.style.display='block'}return false}document.getElementById('profile-current-password').value='';document.getElementById('profile-new-password').value='';document.getElementById('profile-confirm-password').value=''}if(showMessage){ok.textContent='Profile updated successfully.';ok.style.display='block'}return true}
function openModal(type){document.getElementById(type+'-modal').classList.add('active')}
function closeModal(type){document.getElementById(type+'-modal').classList.remove('active')}
function renderCottages(){const grid=document.getElementById('cottages-grid');const query=(document.getElementById('cottage-search')?.value||'').trim().toLowerCase();const filtered=cottages.filter(c=>{if(!query)return true;return [c.name,c.description,c.type,c.amenities,c.pricing_unit,String(c.capacity),String(c.price)].join(' ').toLowerCase().includes(query)});if(!filtered.length){grid.innerHTML=`<div class="empty" style="grid-column:1/-1">${query?'No cottages match your search.':'No cottages available.'}</div>`;return}grid.innerHTML=filtered.map(c=>{const amenities=(c.amenities||'').split(',').map(v=>v.trim()).filter(Boolean);return `<article class="card"><div class="media"><img src="${c.image_url}" alt="${c.name}" onerror="this.src='assets/cottages/paradise-nook-cottage.jpg'"><div class="hover"><h4>${c.name}</h4><p>${c.description||'A tropical stay designed for comfort and easy resort access.'}</p><div class="badges"><span>${c.type}</span><span>${c.capacity} guests</span>${amenities.slice(0,3).map(item=>`<span>${item}</span>`).join('')}</div></div></div><div class="info"><h3>${c.name}</h3><p>${c.description||'A tropical stay designed for comfort and easy resort access.'}</p><div class="meta"><span class="pill">${c.type}</span><span>Capacity: <strong>${c.capacity}</strong></span></div><div class="bottom"><div class="price">${money(c.price)} <small>/ ${c.pricing_unit}</small></div><button class="book" type="button" onclick="openBooking(${c.id})">Book Now</button></div></div></article>`}).join('')}
async function loadCottages(){const grid=document.getElementById('cottages-grid');try{const res=await fetch(`cottages.php?action=list&_=${Date.now()}`,{cache:'no-store'});const text=await res.text();const data=JSON.parse(text);cottages=data.success&&Array.isArray(data.cottages)?data.cottages:[];renderCottages()}catch(e){console.error('Cottage load failed',e);grid.innerHTML='<div class="empty" style="grid-column:1/-1">Could not load cottages.</div>'}}
function openBooking(cottageId){currentCottage=cottages.find(c=>Number(c.id)===Number(cottageId))||null;if(!currentCottage)return;document.getElementById('booking-title').textContent=currentCottage.name;document.getElementById('booking-cottage-name').value=currentCottage.name;document.getElementById('booking-capacity').value=currentCottage.capacity+' guests';document.getElementById('booking-guest-count').value='1';document.getElementById('checkin-date').value=today;const next=new Date();next.setDate(next.getDate()+1);const nextValue=next.toISOString().split('T')[0];document.getElementById('checkout-date').value=nextValue;document.getElementById('checkin-date').min=today;document.getElementById('checkout-date').min=nextValue;document.getElementById('checkin-time').value='14:00';document.getElementById('checkout-time').value='12:00';document.getElementById('book-error').style.display='none';document.getElementById('book-success').style.display='none';updateBookingSummary();checkAvailability();openModal('booking')}
function closeBookingModal(){closeModal('booking')}
function updateBookingSummary(){if(!currentCottage)return;const start=new Date(document.getElementById('checkin-date').value),end=new Date(document.getElementById('checkout-date').value);let units=Math.max(1,Math.round((end-start)/86400000));if(currentCottage.pricing_unit==='event')units=1;const total=Number(currentCottage.price)*units;document.getElementById('booking-total').textContent=money(total);document.getElementById('booking-down-payment').textContent=money(total*.3);document.getElementById('booking-total-meta').textContent=`${units} ${currentCottage.pricing_unit}${units===1?'':'s'} x ${money(currentCottage.price)} | Capacity ${currentCottage.capacity} guests`}
function setAvailability(ok,msg){const el=document.getElementById('availability-status'),btn=document.getElementById('confirm-booking-btn');selectedAvailable=ok;el.textContent=msg;el.className='avail '+(ok?'available':'unavailable');btn.disabled=!ok}
async function checkAvailability(){if(!currentCottage)return;const fd=new FormData();fd.append('action','availability');fd.append('cottage_id',currentCottage.id);fd.append('check_in',document.getElementById('checkin-date').value);fd.append('check_out',document.getElementById('checkout-date').value);fd.append('guest_count',document.getElementById('booking-guest-count').value);setAvailability(false,'Checking availability...');const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){setAvailability(false,data.message||'Unable to check availability.');return}setAvailability(!!data.available,data.message)}
async function confirmBooking(){const err=document.getElementById('book-error'),ok=document.getElementById('book-success');err.style.display='none';ok.style.display='none';await checkAvailability();if(!selectedAvailable){err.textContent='Selected dates are unavailable.';err.style.display='block';return}const fd=new FormData();fd.append('action','book');fd.append('cottage_id',currentCottage.id);fd.append('guest_count',document.getElementById('booking-guest-count').value);fd.append('check_in',document.getElementById('checkin-date').value);fd.append('check_in_time',document.getElementById('checkin-time').value);fd.append('check_out',document.getElementById('checkout-date').value);fd.append('check_out_time',document.getElementById('checkout-time').value);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Booking failed.';err.style.display='block';return}ok.textContent=`Booking submitted. Booking ID: ${data.booking_id}. Down payment: ${money(data.down_payment)}.`;ok.style.display='block';await loadNotifications();showTab('bookings')}
async function fetchMyBookings(){try{const fd=new FormData();fd.append('action','my_bookings');const res=await fetch('reservations.php',{method:'POST',body:fd,cache:'no-store'});const data=await res.json();return data.success?data.bookings:[]}catch(e){console.error('Booking load failed',e);return[]}}
function formatDate(value){if(!value)return'N/A';const d=new Date(value);return d.toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'})}
function markViewed(){const keys=(JSON.parse(localStorage.getItem('paradise_viewed_notifications')||'[]'));const seen=new Set(keys);bookings.filter(b=>b.status==='confirmed'||b.status==='cancelled').forEach(b=>seen.add(`${b.booking_id}:${b.status}`));localStorage.setItem('paradise_viewed_notifications',JSON.stringify([...seen]))}
function renderNotifications(){const list=document.getElementById('notify-list'),counter=document.getElementById('notify-count');const viewed=new Set(JSON.parse(localStorage.getItem('paradise_viewed_notifications')||'[]'));const updates=bookings.filter(b=>b.status==='confirmed'||b.status==='cancelled');const unread=updates.filter(b=>!viewed.has(`${b.booking_id}:${b.status}`)).length;counter.textContent=unread;counter.classList.toggle('show',unread>0);if(!updates.length){list.innerHTML='<div class="empty" style="padding:18px 10px">No booking updates yet.</div>';return}list.innerHTML=updates.map(b=>`<div class="notify-item"><div class="notify-top"><div class="notify-title">${b.cottage_name}</div><span class="status ${b.status}">${b.status.charAt(0).toUpperCase()+b.status.slice(1)}</span></div><div class="notify-meta">Booking ID: ${b.booking_id}<br>Check-in: ${formatDate(b.check_in)} ${b.check_in_time||''}<br>Check-out: ${formatDate(b.check_out)} ${b.check_out_time||''}</div></div>`).join('')}
async function loadNotifications(){bookings=await fetchMyBookings();renderNotifications()}
function toggleNotifications(){const panel=document.getElementById('notify-panel'),open=!panel.classList.contains('active');panel.classList.toggle('active');if(open){markViewed();renderNotifications()}}
async function loadMyBookings(){const container=document.getElementById('bookings-container');container.innerHTML='<div class="empty">Loading bookings...</div>';bookings=await fetchMyBookings();renderNotifications();if(!bookings.length){container.innerHTML='<div class="empty">No bookings yet.</div>';return}container.innerHTML=bookings.map(b=>`<div class="booking-card"><div class="booking-head" style="--booking-bg:url('${(b.image_url||'assets/cottages/paradise-nook-cottage.jpg').replace(/'/g,"%27")}')"><div><h3 style="font-family:Playfair Display,serif;font-size:1.15rem">${b.cottage_name}</h3><small>Booking ID: ${b.booking_id}</small></div><span class="status ${b.status}">${b.status.charAt(0).toUpperCase()+b.status.slice(1)}</span></div><div class="booking-body" style="--booking-bg:url('${(b.image_url||'assets/cottages/paradise-nook-cottage.jpg').replace(/'/g,"%27")}')"><div class="booking-list"><div class="booking-line"><div><strong>Guest</strong><span>${b.display_guest_name||profile?.full_name||'Customer'}</span></div></div><div class="booking-line"><div><strong>Check-In</strong><span>${formatDate(b.check_in)} ${b.check_in_time||''}</span></div></div><div class="booking-line"><div><strong>Check-Out</strong><span>${formatDate(b.check_out)} ${b.check_out_time||''}</span></div></div><div class="booking-line"><div><strong>Guests</strong><span>${b.guest_count||1}</span></div></div></div><div class="summary"><div class="big">${money(b.total_amount)}</div><div class="small">Down payment: ${money(b.down_payment||0)}<br>Cottage Type: ${b.cottage_type}<br>Booked on: ${formatDate(b.booked_on||b.created_at)}</div>${b.status!=='cancelled'?`<button class="cancel-btn" type="button" onclick="cancelBooking('${b.booking_id}')">Cancel Booking</button>`:''}</div></div></div>`).join('')}
async function cancelBooking(id){if(!confirm('Cancel this booking?'))return;const fd=new FormData();fd.append('action','cancel');fd.append('booking_id',id);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){alert(data.message||'Could not cancel booking.');return}await loadNotifications();loadMyBookings()}
async function logout(){const fd=new FormData();fd.append('action','logout');await fetch('auth.php',{method:'POST',body:fd});window.location.href='index.php'}
document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)el.classList.remove('active')}));document.addEventListener('click',e=>{const wrap=document.querySelector('.notify-wrap');if(wrap&&!wrap.contains(e.target))document.getElementById('notify-panel').classList.remove('active')});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay.active').forEach(el=>el.classList.remove('active'))})
document.addEventListener('input',e=>{if(e.target&&e.target.id==='cottage-search')renderCottages()});
['booking-guest-count','checkin-date','checkin-time','checkout-date','checkout-time'].forEach(id=>document.addEventListener('change',e=>{if(e.target&&e.target.id===id){if(id==='checkin-date'){const v=document.getElementById('checkin-date').value;if(v){const next=new Date(v);next.setDate(next.getDate()+1);document.getElementById('checkout-date').min=next.toISOString().split('T')[0];if(document.getElementById('checkout-date').value<=v){document.getElementById('checkout-date').value=next.toISOString().split('T')[0]}}}updateBookingSummary();checkAvailability()}}));
async function boot(){await loadCottages();await loadProfile();await loadNotifications();refreshTimer=setInterval(()=>{loadNotifications()},10000)} boot();
</script>
</body>
</html>
